package com.centrepay.mobile;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public class TeacherListActivity extends Activity{
 static final int P=Palette.PRIMARY,D=Palette.PRIMARY_DARK,BG=Palette.BACKGROUND,T=Palette.TEXT,M=Palette.MUTED,B=Palette.BORDER,S=Palette.SUCCESS,W=Palette.WARNING; StudentDatabaseHelper db; LinearLayout list; EditText search; TextView count;HorizontalScrollView filters; String selectedFilter="Tous",selectedStatus="",selectedSort="Nom";
 public void onCreate(Bundle x){super.onCreate(x);getWindow().setStatusBarColor(D);getWindow().setNavigationBarColor(Color.WHITE);db=new StudentDatabaseHelper(this);LinearLayout root=col();root.setBackgroundColor(BG);root.addView(header(),lp(-1,124));LinearLayout body=col();body.setPadding(dp(16),dp(18),dp(16),0);LinearLayout title=row();title.setGravity(Gravity.CENTER_VERTICAL);title.addView(txt("Professeurs",24,T,true),lp(0,-2,1));count=txt("0 professeurs",13,M,false);title.addView(count);body.addView(title);body.addView(txt("Liste de vos professeurs et de leurs informations.",14,M,false),margins(-1,-2,0,dp(4),0,dp(14)));body.addView(searchBar(),lp(-1,52));filters=(HorizontalScrollView)filterBar();body.addView(filters,margins(-1,44,0,dp(12),0,0));ScrollView sv=new ScrollView(this);list=col();list.setPadding(0,dp(14),0,dp(100));sv.addView(list);body.addView(sv,lp(-1,0,1));root.addView(body,lp(-1,0,1));root.addView(nav());FrameLayout f=new FrameLayout(this);f.addView(root);LinearLayout fab=col();fab.setGravity(Gravity.CENTER);TextView plus=txt("+",32,Color.WHITE,false);plus.setGravity(17);plus.setElevation(dp(8));plus.setBackground(round(P,28));fab.addView(plus,lp(56,56));TextView addLabel=txt("Ajouter",11,P,true);addLabel.setGravity(17);fab.addView(addLabel,lp(64,18));fab.setOnClickListener(v->startActivity(new Intent(this,AddTeacherActivity.class)));FrameLayout.LayoutParams q=new FrameLayout.LayoutParams(dp(76),dp(78),Gravity.RIGHT|Gravity.BOTTOM);q.setMargins(0,0,dp(10),dp(78));f.addView(fab,q);setContentView(f);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render(s.toString());}public void afterTextChanged(Editable e){}});}
 protected void onResume(){super.onResume();if(list!=null)render(search.getText().toString());}
 View header(){LinearLayout h=col();h.setPadding(dp(20),dp(14),dp(20),dp(10));GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{P,D});g.setCornerRadii(new float[]{0,0,0,0,0,0,dp(22),dp(22)});h.setBackground(g);LinearLayout r=row();r.addView(txt("Centre",25,Color.WHITE,true));r.addView(txt("Pay",25,Color.rgb(244,194,78),true));r.addView(new View(this),lp(0,32,1));TextView a=txt("CP",14,Color.WHITE,true);a.setGravity(17);a.setBackground(round(Color.argb(70,255,255,255),20));r.addView(a,lp(40,40));h.addView(r);h.addView(txt("Professeurs · équipe enseignante",13,Color.WHITE,false));return h;}
 View searchBar(){LinearLayout r=row();r.setGravity(16);r.setPadding(dp(12),0,dp(8),0);r.setBackground(roundStroke(Color.WHITE,16,B));r.addView(icon(R.drawable.ic_search_24,M,22),lp(30,-1));search=new EditText(this);search.setSingleLine();search.setTextSize(14);search.setHint("Rechercher un professeur...");search.setHintTextColor(M);search.setTextColor(T);search.setBackgroundColor(Color.TRANSPARENT);r.addView(search,lp(0,-1,1));ImageView tune=icon(R.drawable.ic_tune_24,M,22);tune.setPadding(dp(3),dp(3),dp(3),dp(3));tune.setOnClickListener(v->showSort());r.addView(tune,lp(32,-1));return r;}
 View filterBar(){HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout line=row();String[] values={"Tous","Maths","Anglais","Physique","Français"};for(String value:values){TextView chip=filterChip(value,value.equals(selectedFilter));chip.setOnClickListener(v->{selectedFilter=value;rebuildFilters(scroll);render(search.getText().toString());});line.addView(chip,margins(-2,40,0,0,8,0));}String statusLabel=selectedStatus.isEmpty()?"Statut ⌄":selectedStatus+" ⌄";TextView status=filterChip(statusLabel,!selectedStatus.isEmpty());status.setOnClickListener(v->showStatus());line.addView(status,margins(-2,40,0,0,8,0));scroll.addView(line);return scroll;}
 void rebuildFilters(HorizontalScrollView old){ViewGroup parent=(ViewGroup)old.getParent();int index=parent.indexOfChild(old);parent.removeViewAt(index);filters=(HorizontalScrollView)filterBar();parent.addView(filters,index,margins(-1,44,0,dp(12),0,0));}
 TextView filterChip(String s,boolean active){TextView v=txt(s+(s.equals("Tous")?" ("+db.findTeachers("").size()+")":""),14,active?Color.WHITE:T,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(16),0,dp(16),0);v.setBackground(active?round(P,20):roundStroke(Color.rgb(241,245,249),20,Color.rgb(226,232,240)));return v;}
 boolean matchesFilter(Teacher t){if(selectedFilter.equals("Tous"))return true;String s=t.subjects==null?"":t.subjects.toLowerCase(Locale.ROOT);if(selectedFilter.equals("Maths"))return s.contains("math");if(selectedFilter.equals("Anglais"))return s.contains("anglais");if(selectedFilter.equals("Physique"))return s.contains("phys")||s.contains("pc");return s.contains("fran");}
 boolean matchesStatus(Teacher t){if(selectedStatus.isEmpty())return true;if(selectedStatus.equals("Inactifs"))return !t.active;TeacherBalance b=db.getTeacherBalance(t.id,currentMonth());int due=b==null?0:b.remainingAmount;return selectedStatus.equals("À verser")?due>0:due<=0&&t.active;}
 void render(String q){list.removeAllViews();List<Teacher> ts=new ArrayList<>(db.findTeachers(q.trim()));ts.removeIf(t->!matchesFilter(t)||!matchesStatus(t));if(selectedSort.equals("Reste dû"))ts.sort((a,b)->Integer.compare(monthDue(b),monthDue(a)));else if(selectedSort.equals("Matière"))ts.sort(Comparator.comparing(t->t.subjects==null?"":t.subjects,String.CASE_INSENSITIVE_ORDER));else ts.sort(Comparator.comparing(t->t.fullName,String.CASE_INSENSITIVE_ORDER));int shown=0;for(Teacher t:ts){shown++;list.addView(card(t),margins(-1,-2,0,0,0,12));}count.setText(shown+" professeur"+(shown>1?"s":""));if(shown==0){TextView empty=txt("Aucun professeur ne correspond aux filtres.",15,M,false);empty.setGravity(Gravity.CENTER);empty.setPadding(0,dp(32),0,dp(32));list.addView(empty);}}
 int monthDue(Teacher t){TeacherBalance b=db.getTeacherBalance(t.id,currentMonth());return b==null?0:Math.max(0,b.remainingAmount);}
 View card(Teacher t){int due=monthDue(t);LinearLayout c=col();c.setPadding(dp(14),dp(14),dp(12),dp(14));c.setMinimumHeight(dp(122));c.setElevation(dp(3));c.setBackground(round(Color.WHITE,18));c.setOnClickListener(v->openTeacher(t));LinearLayout r=row();TextView av=txt(initials(t.fullName),16,Color.rgb(6,95,70),true);av.setGravity(17);av.setBackground(round(Color.rgb(223,247,236),22));r.addView(av,lp(48,48));LinearLayout info=col();info.addView(txt(t.fullName,16,T,true));LinearLayout ph=row();ph.setGravity(Gravity.CENTER_VERTICAL);ph.addView(icon(R.drawable.ic_call_24,D,16),lp(18,18));ph.addView(txt(t.phone==null||t.phone.trim().isEmpty()?"Téléphone non renseigné":t.phone,12,M,false),margins(-2,-2,dp(5),0,0,0));info.addView(ph);info.addView(subjectChips(t.subjects),margins(-1,30,0,dp(5),0,0));LinearLayout levels=row();levels.setGravity(Gravity.CENTER_VERTICAL);levels.addView(icon(R.drawable.ic_school_24,M,17),lp(20,20));levels.addView(txt(pretty(t.level)+" · "+db.getTeacherStudentCount(t.id)+" élève(s)",11,M,false),margins(-2,-2,dp(4),0,0,0));info.addView(levels);r.addView(info,margins(0,-2,12,0,8,0,1));View divider=new View(this);divider.setBackgroundColor(B);r.addView(divider,margins(1,-1,0,0,10,0));LinearLayout right=col();right.setGravity(Gravity.RIGHT);LinearLayout cap=row();cap.setGravity(Gravity.CENTER_VERTICAL);cap.addView(txt("À verser ce mois",11,M,false),lp(0,-2,1));ImageView more=icon(R.drawable.ic_more_vert_24,M,20);more.setPadding(dp(2),dp(2),dp(2),dp(2));more.setOnClickListener(v->showActions(t));cap.addView(more,lp(28,28));right.addView(cap);right.addView(txt(money(due),20,T,true));TextView st=txt(!t.active?"Inactif":due>0?"À verser":"À jour",12,!t.active?M:due>0?W:S,true);st.setGravity(Gravity.CENTER);st.setPadding(dp(10),dp(5),dp(10),dp(5));st.setBackground(round(!t.active?0xfff1f5f9:due>0?Color.rgb(254,247,224):Color.rgb(236,253,245),16));right.addView(st,margins(-2,-2,0,dp(7),0,0));r.addView(right,lp(142,-2));c.addView(r);return c;}
 void showStatus(){String[] a={"Tous les statuts","À jour","À verser","Inactifs"};new AlertDialog.Builder(this).setTitle("Statut du professeur").setItems(a,(d,w)->{selectedStatus=w==0?"":a[w];if(filters!=null)rebuildFilters(filters);render(search.getText().toString());}).show();}
 void showSort(){String[] a={"Nom","Matière","Reste dû"};new AlertDialog.Builder(this).setTitle("Trier les professeurs").setItems(a,(d,w)->{selectedSort=a[w];render(search.getText().toString());}).show();}
 void showActions(Teacher t){ArrayList<String>a=new ArrayList<>();a.add("Ouvrir la fiche");if(t.phone!=null&&!t.phone.trim().isEmpty())a.add("Appeler "+t.phone);new AlertDialog.Builder(this).setTitle(t.fullName).setItems(a.toArray(new String[0]),(d,w)->{if(w==0)openTeacher(t);else startActivity(new Intent(Intent.ACTION_DIAL,android.net.Uri.parse("tel:"+t.phone.replace(" ",""))));}).show();}
 void openTeacher(Teacher t){Intent i=new Intent(this,TeacherMonthlySalaryActivity.class);i.putExtra(TeacherMonthlySalaryActivity.EXTRA_TEACHER_ID,t.id);startActivity(i);}
 String currentMonth(){Calendar c=Calendar.getInstance();return String.format(Locale.US,"%04d-%02d",c.get(Calendar.YEAR),c.get(Calendar.MONTH)+1);}
 View subjectChips(String raw){LinearLayout line=row();if(raw==null)return line;int used=0;for(String part:raw.split(",")){if(used++>=2)break;String name=part.trim();int bg=Color.rgb(223,247,236),fg=Color.rgb(6,95,70);String low=name.toLowerCase(Locale.ROOT);if(low.contains("phys")||low.equals("pc")){bg=Palette.BLUE_SOFT;fg=Color.rgb(30,64,175);}else if(low.contains("fran")){bg=Color.rgb(252,231,243);fg=Color.rgb(190,24,93);}else if(low.contains("anglais")){bg=Palette.WARNING_SOFT;fg=Color.rgb(146,64,14);}TextView chip=txt(name,11,fg,false);chip.setGravity(Gravity.CENTER);chip.setPadding(dp(8),0,dp(8),0);chip.setBackground(round(bg,14));line.addView(chip,margins(-2,26,0,0,5,0));}return line;}
 View nav(){return BottomTabBar.create(this,TeacherListActivity.class);}
 void tab(LinearLayout r,int res,String s,boolean on,View.OnClickListener l){LinearLayout t=col();t.setGravity(Gravity.CENTER);t.setPadding(dp(2),dp(2),dp(2),0);if(l!=null)t.setOnClickListener(l);FrameLayout iconBox=new FrameLayout(this);ImageView image=icon(res,on?P:M,24);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(28),dp(28),Gravity.CENTER);iconBox.addView(image,ip);if(on)iconBox.setBackground(round(Palette.PRIMARY_SOFT,18));t.addView(iconBox,lp(64,34));TextView label=txt(s,12,on?P:M,on);label.setGravity(Gravity.CENTER);label.setPadding(0,dp(4),0,0);t.addView(label,lp(64,24));r.addView(t,lp(0,-1,1));}
 void tabDummy(){}
 ImageView icon(int r,int c,int z){ImageView i=new ImageView(this);i.setImageResource(r);i.setColorFilter(c);return i;} String initials(String n){String[] p=n.trim().split("\\s+");return (p[0].substring(0,1)+(p.length>1?p[p.length-1].substring(0,1):"")).toUpperCase();}String label(String s){return s==null?"":s.replace(","," · ");}String pretty(String s){return s==null?"":s.replace(","," · ");}String money(int n){return String.format(Locale.FRANCE,"%,d DH",n).replace(',',' ');} TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setIncludeFontPadding(false);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}LinearLayout col(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}LinearLayout row(){return new LinearLayout(this);}GradientDrawable round(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}GradientDrawable roundStroke(int c,int r,int s){GradientDrawable g=round(c,r);g.setStroke(dp(1),s);return g;}LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}LinearLayout.LayoutParams lp(int w,int h,float q){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h),q);}LinearLayout.LayoutParams margins(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=lp(w,h);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}LinearLayout.LayoutParams margins(int w,int h,int l,int t,int r,int b,float q){LinearLayout.LayoutParams p=lp(w,h,q);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
